<template><view><PageHeader search transparent :scrolled="scrollTop>400"/><ModuleContent v-if="data" :modules="data.modules"/><view v-else class="state" @click="load">{{error||'加载中…'}}</view><BrandFooter/><button class="floating-back" aria-label="返回" @click="back">‹</button></view></template>
<script setup>import {ref} from 'vue';const scrollTop=ref(0);onPageScroll(e=>scrollTop.value=e.scrollTop);import {onPageScroll} from '@dcloudio/uni-app';import {onLoad} from '@dcloudio/uni-app';import {request,back} from '../../lib/content';import PageHeader from '../../components/PageHeader.vue';import ModuleContent from '../../components/ModuleContent.vue';import BrandFooter from '../../components/BrandFooter.vue';const data=ref(null),error=ref('');let id;const load=async()=>{error.value='';try{data.value=await request('module/page.json',{key:'module_page',id},'module'+id)}catch(e){error.value=e.message}};onLoad(o=>{id=o.id;load()})</script>
<style scoped>.floating-back{position:fixed;bottom:80rpx;right:24rpx;width:70rpx;height:70rpx;background:#fff;border-radius:50%;box-shadow:0 2rpx 8rpx #0002;padding:0;line-height:62rpx;font-size:55rpx}.state{text-align:center;padding:100rpx 40rpx;color:#999}</style>
